create extension if not exists "pgcrypto";create table if not exists public.guests(id uuid primary key default gen_random_uuid(),name text not null,email text,phone text,attending boolean not null default false,plus_one text,children text,menu text,allergies text,song_request text,message text,created_at timestamptz not null default now());create table if not exists public.photos(id uuid primary key default gen_random_uuid(),guest_name text not null default 'Invité',caption text,storage_path text not null,approved boolean not null default false,created_at timestamptz not null default now());alter table public.guests enable row level security;alter table public.photos enable row level security;create policy "public insert guests" on public.guests for insert to anon,authenticated with check(true);create policy "admin read guests" on public.guests for select to authenticated using(true);create policy "public insert photos" on public.photos for insert to anon,authenticated with check(approved=false);create policy "public approved photos" on public.photos for select to anon using(approved=true);create policy "admin read photos" on public.photos for select to authenticated using(true);create policy "admin update photos" on public.photos for update to authenticated using(true) with check(true);insert into storage.buckets(id,name,public) values('wedding-photos','wedding-photos',true) on conflict(id) do update set public=true;create policy "public upload wedding photos" on storage.objects for insert to anon,authenticated with check(bucket_id='wedding-photos');